-- Đưa vào migration những gì trước đây các script setup_*_bucket.js, upload_to_supabase_storage.js,
-- update_recipe_videos.js tạo trực tiếp qua exec_seed_sql (không có trong lịch sử migration).

ALTER TABLE public.recipes ADD COLUMN IF NOT EXISTS video_url TEXT;

INSERT INTO storage.buckets (id, name, public) VALUES
    ('recipe-images', 'recipe-images', true),
    ('recipe-videos', 'recipe-videos', true)
ON CONFLICT (id) DO UPDATE SET public = true;

-- Ai cũng xem được (bucket công khai). Upload/ghi đè chỉ qua service_role (Dashboard / supabase storage cp).
DROP POLICY IF EXISTS "Allow anon upload" ON storage.objects;
DROP POLICY IF EXISTS "Allow anon update" ON storage.objects;
DROP POLICY IF EXISTS "Allow anon upload videos" ON storage.objects;
DROP POLICY IF EXISTS "Allow anon update videos" ON storage.objects;
DROP POLICY IF EXISTS "Public Access" ON storage.objects;
CREATE POLICY "Public Access" ON storage.objects FOR SELECT USING (bucket_id = 'recipe-images');
DROP POLICY IF EXISTS "Public Access Videos" ON storage.objects;
CREATE POLICY "Public Access Videos" ON storage.objects FOR SELECT USING (bucket_id = 'recipe-videos');

